1	<!DOCTYPE html>
2	<html lang="zh">
3	<head>
4	<meta charset="UTF-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1, user-scalable=no">
6	<title>Starfall Bulwark 坠星壁垒</title>
7	<style>
8	  html,body{margin:0;height:100%;overflow:hidden;background:#0d0b1e;font-family:"Microsoft YaHei",system-ui,sans-serif;user-select:none;-webkit-user-select:none}
9	  #gl{position:fixed;inset:0;width:100%;height:100%;display:block}
10	  .panel{background:rgba(18,12,28,.82);border:1px solid rgba(255,215,122,.22);border-radius:10px;backdrop-filter:blur(3px)}
11	
12	  /* top-left hud */
13	  #hud{position:fixed;left:14px;top:12px;z-index:10;color:#e8dcc8;display:flex;flex-direction:column;gap:7px;pointer-events:none}
14	  #corebar{display:flex;align-items:center;gap:8px}
15	  #corebar .gem{font-size:20px;color:#6fe8d8;filter:drop-shadow(0 0 6px #2ec9b8)}
16	  #coretrack{width:190px;height:14px;background:rgba(8,6,16,.8);border:1px solid rgba(111,232,216,.3);border-radius:7px;overflow:hidden}
17	  #corefill{height:100%;width:100%;border-radius:6px;transition:width .25s}
18	  #corenum{font-size:12px;color:#9fd8d0;min-width:40px}
19	  #essence{font-size:17px;color:#ffd77a;text-shadow:0 0 8px rgba(255,180,80,.5)}
20	  #wavetag{font-size:14px;color:#d8c8e8}
21	  #preview{font-size:11px;color:#a898c0;max-width:280px;line-height:1.35}
22	  #besttag{font-size:11px;color:#c8a86a}
23	  #epop{position:fixed;left:150px;top:70px;font-size:15px;color:#ffd77a;opacity:0;z-index:11;pointer-events:none;text-shadow:0 0 8px rgba(255,190,90,.8)}
24	  #epop.pop{animation:epop 1s ease-out}
25	  @keyframes epop{0%{opacity:1;transform:translateY(0)}100%{opacity:0;transform:translateY(-26px)}}
26	
27	  /* boss bar */
28	  #bossbar{position:fixed;top:14px;left:50%;transform:translateX(-50%);width:min(480px,60vw);display:none;z-index:10;pointer-events:none}
29	  #bossname{font-size:13px;color:#f0c8b0;text-align:center;letter-spacing:3px;margin-bottom:4px;text-shadow:0 0 6px rgba(220,90,60,.6)}
30	  #bosstrack{height:12px;background:rgba(10,6,10,.85);border:1px solid rgba(230,120,80,.4);border-radius:6px;overflow:hidden}
31	  #bossfill{height:100%;width:100%;background:linear-gradient(90deg,#c94a2e,#e88a5f);transition:width .2s}
32	
33	  /* top-right buttons */
34	  #tr{position:fixed;right:14px;top:12px;z-index:12;display:flex;gap:8px;align-items:flex-start}
35	  #tr button{width:40px;height:40px;border-radius:9px;border:1px solid rgba(255,215,122,.3);background:rgba(18,12,28,.85);color:#ffd77a;font-size:16px;cursor:pointer}
36	  #tr button.on{background:rgba(90,60,20,.9)}
37	  #bestwrap{position:fixed;right:14px;top:58px;z-index:10;color:#c8a86a;font-size:12px;text-align:right;pointer-events:none}
38	
39	  /* call wave */
40	  #callbtn{position:fixed;bottom:118px;left:50%;transform:translateX(-50%);z-index:12;display:none;padding:10px 26px;font-size:16px;color:#0e0a18;background:linear-gradient(180deg,#ffd77a,#e8a84f);border:none;border-radius:22px;cursor:pointer;letter-spacing:2px;box-shadow:0 0 18px rgba(255,190,90,.45)}
41	  #callbtn.bonus{animation:pulse 1.2s infinite}
42	  @keyframes pulse{0%,100%{box-shadow:0 0 12px rgba(255,190,90,.35)}50%{box-shadow:0 0 26px rgba(255,200,100,.75)}}
43	
44	  /* build cards */
45	  #cardwrap{position:fixed;bottom:12px;left:50%;transform:translateX(-50%);z-index:12;text-align:center;pointer-events:none}
46	  #cardeh{font-size:12px;color:#a898c0;margin-bottom:6px;text-shadow:0 1px 4px #000}
47	  #cards{display:none;gap:9px;pointer-events:none;justify-content:center}
48	  #cards.on{display:flex}
49	  .card{position:relative;width:78px;padding:9px 4px 7px;background:rgba(18,12,28,.9);border:1px solid rgba(255,215,122,.25);border-radius:10px;cursor:pointer;text-align:center;transition:transform .12s,border-color .12s;pointer-events:auto}
50	  .card:hover{transform:translateY(-3px);border-color:rgba(255,215,122,.7)}
51	  .card.dim{opacity:.38;pointer-events:none}
52	  .card .glyph{font-size:21px}
53	  .card .cn{font-size:12px;color:#e8dcc8;margin-top:2px}
54	  .card .cc{font-size:11px;color:#ffd77a}
55	  .card .ck{position:absolute;left:5px;top:4px;font-size:10px;color:#8a7aa0}
56	
57	  /* actives skill bar */
58	  #skills{position:fixed;right:14px;bottom:14px;z-index:13;display:flex;gap:10px}
59	  .skill{position:relative;width:52px;height:52px;border-radius:10px;background:rgba(18,12,28,.85);border:1px solid rgba(255,215,122,.3);cursor:pointer;overflow:hidden;display:flex;align-items:center;justify-content:center}
60	  .skill .sg{font-size:24px;color:#c8bca8;transition:color .2s}
61	  .skill.ready .sg{color:#ffe0a8;text-shadow:0 0 10px rgba(255,190,90,.8)}
62	  .skill .scd{position:absolute;left:0;bottom:0;width:100%;height:0;background:rgba(8,5,16,.72);pointer-events:none}
63	  .skill .sk{position:absolute;right:3px;bottom:1px;font-size:10px;color:#8a7aa0}
64	  .skill:not(.ready){border-color:rgba(255,215,122,.15)}
65	
66	  /* tower panel */
67	  #tpanel{position:fixed;right:14px;top:96px;z-index:12;width:210px;padding:12px;display:none;color:#e8dcc8;pointer-events:auto}
68	  #tpname{font-size:15px;color:#ffd77a;margin-bottom:6px}
69	  #tpstats{font-size:12px;color:#c8bca8;line-height:1.5}
70	  #tpeh{font-size:11px;color:#8fc8bc;margin:6px 0 10px}
71	  #tpanel button{display:block;width:100%;margin-top:8px;padding:8px;border-radius:8px;border:1px solid rgba(255,215,122,.35);background:rgba(50,36,20,.85);color:#ffd77a;font-size:13px;cursor:pointer}
72	  #tpanel button.off{opacity:.45;pointer-events:none}
73	  #tpx{position:absolute;right:8px;top:8px;width:22px;height:22px;padding:0!important;background:none!important;border:none!important;color:#8a7aa0;font-size:14px}
74	
75	  /* banner / toast / flash */
76	  #banner{position:fixed;top:26%;left:50%;transform:translate(-50%,-50%);z-index:14;text-align:center;opacity:0;transition:opacity .3s;pointer-events:none}
77	  #banner.on{opacity:1}
78	  #banner .bmain{font-size:30px;color:#ffe0a8;letter-spacing:8px;text-shadow:0 0 18px rgba(255,180,80,.7),0 2px 8px #000}
79	  #banner .bsub{font-size:14px;color:#c8b090;margin-top:8px;letter-spacing:2px;text-shadow:0 1px 6px #000}
80	  #toast{position:fixed;bottom:170px;left:50%;transform:translateX(-50%);z-index:14;background:rgba(18,12,28,.9);border:1px solid rgba(255,215,122,.3);color:#e8dcc8;font-size:13px;padding:8px 18px;border-radius:18px;opacity:0;transition:opacity .25s;pointer-events:none}
81	  #toast.on{opacity:1}
82	  #flash{position:fixed;inset:0;z-index:9;pointer-events:none;background:radial-gradient(ellipse at center,transparent 55%,rgba(200,30,30,.5));opacity:0}
83	  #flash.on{animation:fl .5s ease-out}
84	  @keyframes fl{0%{opacity:1}100%{opacity:0}}
85	
86	  /* draft overlay */
87	  #draft{position:fixed;inset:0;z-index:20;display:none;background:rgba(8,5,16,.6);flex-direction:column;align-items:center;justify-content:center;gap:18px}
88	  #draft .dtitle{font-size:22px;color:#ffe0a8;letter-spacing:6px;text-shadow:0 0 14px rgba(255,190,90,.6)}
89	  #draft .dcards{display:flex;gap:16px}
90	  .dcard{width:180px;padding:18px 14px;background:rgba(24,16,38,.95);border:1px solid rgba(255,215,122,.4);border-radius:14px;text-align:center;cursor:pointer;transition:transform .15s,border-color .15s}
91	  .dcard:hover{transform:translateY(-5px);border-color:#ffd77a;box-shadow:0 0 24px rgba(255,190,90,.3)}
92	  .dcard .dg{font-size:30px;color:#ffd77a}
93	  .dcard .dn{font-size:16px;color:#ffe8c8;margin:8px 0 6px}
94	  .dcard .dd{font-size:12px;color:#a898b8;line-height:1.5}
95	  .dcard .dk{margin-top:10px;font-size:11px;color:#8a7aa0}
96	
97	  /* title & end */
98	  #title,#end{position:fixed;inset:0;z-index:30;display:flex;flex-direction:column;align-items:center;justify-content:center;background:radial-gradient(ellipse at 50% 38%,rgba(30,16,44,.55),rgba(8,5,16,.92));text-align:center}
99	  #title h1{font-size:52px;color:#ffe0a8;letter-spacing:14px;margin:0;text-shadow:0 0 26px rgba(255,180,80,.55),0 3px 10px #000}
100	  #title h2{font-size:15px;color:#8fc8bc;letter-spacing:6px;margin:10px 0 22px;font-weight:normal}
101	  #titlebest{font-size:14px;color:#c8a86a;margin-bottom:26px}
102	  .btns{display:flex;gap:14px}
103	  #startbtn,#go,#go2{padding:13px 44px;font-size:18px;letter-spacing:4px;border:none;border-radius:26px;cursor:pointer;background:linear-gradient(180deg,#ffd77a,#e8a84f);color:#14101e;box-shadow:0 0 22px rgba(255,190,90,.4)}
104	  #go2{display:none;background:linear-gradient(180deg,#7fe8d8,#3aa898);color:#0e161a;box-shadow:0 0 22px rgba(90,220,200,.4)}
105	  #end{display:none}
106	  #endh{font-size:44px;color:#ffe0a8;letter-spacing:10px;margin:0;text-shadow:0 0 20px rgba(255,180,80,.5)}
107	  #endd{font-size:15px;color:#c8b8a0;margin:16px 0 26px}
108	
109	  /* touch */
110	  #touch{display:none}
111	  #touch.on{display:block}
112	  #touch .tbtn{position:fixed;z-index:15;width:52px;height:52px;border-radius:50%;background:rgba(18,12,28,.75);border:1px solid rgba(255,215,122,.35);color:#ffd77a;font-size:12px;display:flex;align-items:center;justify-content:center;pointer-events:auto}
113	  #twave{right:80px;bottom:24px;width:64px!important;height:64px!important;font-size:13px!important}
114	  #tspeed{right:150px;bottom:30px}
115	  #tpause{right:150px;bottom:96px}
116	  #tq{right:220px;bottom:30px}#te{right:220px;bottom:96px}#tr{right:220px;bottom:162px}
117	  #tb1,#tb2,#tb3,#tb4,#tb5{right:18px}
118	  #tb1{bottom:104px}#tb2{bottom:160px}#tb3{bottom:216px}#tb4{bottom:272px}#tb5{bottom:328px}
119	
120	  @media (max-width:720px){
121	    #title h1{font-size:34px;letter-spacing:8px}
122	    .card{width:60px}
123	    #preview{max-width:180px}
124	    #coretrack{width:130px}
125	  }
126	</style>
127	<script>window.__BOOTERR=[];window.addEventListener('error',e=>{window.__BOOTERR.push(String(e.message||e));if(window.__G&&window.__G.err)window.__G.err.push(String(e.message||e));});</script>
128	</head>
129	<body>
130	<canvas id="gl"></canvas>
131	
132	<div id="hud">
133	  <div id="corebar"><span class="gem">◆</span><div id="coretrack"><div id="corefill"></div></div><span id="corenum">20/20</span></div>
134	  <div id="essence">✦ 0</div>
135	  <div id="wavetag">第 0 / 10 波</div>
136	  <div id="preview"></div>
137	  <div id="besttag"></div>
138	</div>
139	<div id="epop"></div>
140	
141	<div id="bossbar"><div id="bossname"></div><div id="bosstrack"><div id="bossfill"></div></div></div>
142	
143	<div id="tr">
144	  <button id="mutebtn" title="静音">🔊</button>
145	  <button id="pausebtn" title="暂停 (P)">❚❚</button>
146	  <button id="speedbtn" title="变速 (F)">1×</button>
147	</div>
148	<div id="bestwrap"></div>
149	
150	<button id="callbtn">▶ 召唤下一波</button>
151	
152	<div id="cardwrap"><div id="cardeh">点击发光石台建造</div><div id="cards"></div></div>
153	
154	<div id="tpanel" class="panel">
155	  <button id="tpx">✕</button>
156	  <div id="tpname"></div>
157	  <div id="tpstats"></div>
158	  <div id="tpeh"></div>
159	  <button id="tpup">升级</button>
160	  <button id="tpsell">出售</button>
161	</div>
162	
163	<div id="banner"><div class="bmain"></div><div class="bsub"></div></div>
164	<div id="toast"></div>
165	<div id="flash"></div>
166	<div id="skills"></div>
167	
168	<div id="draft"><div class="dtitle"></div><div class="dcards"></div></div>
169	
170	<div id="title">
171	  <h1>坠星壁垒</h1>
172	  <h2>STARFALL BULWARK · 塔防坚守</h2>
173	  <div id="titlebest"></div>
174	  <div class="btns"><button id="startbtn">入 守</button></div>
175	</div>
176	
177	<div id="end">
178	  <h1 id="endh"></h1>
179	  <div id="endd"></div>
180	  <div class="btns"><button id="go">重整旗鼓</button><button id="go2">无尽坚守</button></div>
181	</div>
182	
183	<div id="touch">
184	  <div class="tbtn" id="twave">召唤</div>
185	  <div class="tbtn" id="tspeed">变速</div>
186	  <div class="tbtn" id="tpause">暂停</div>
187	  <div class="tbtn" id="tq">陨</div>
188	  <div class="tbtn" id="te">冻</div>
189	  <div class="tbtn" id="tr">过</div>
190	  <div class="tbtn" id="tb1">弩</div>
191	  <div class="tbtn" id="tb2">霜</div>
192	  <div class="tbtn" id="tb3">雷</div>
193	  <div class="tbtn" id="tb4">炮</div>
194	  <div class="tbtn" id="tb5">镜</div>
195	</div>
196	
197	<script type="module" src="js/game.js"></script>
198	</body>
