931	
932	  // T30 full 10-wave cruise — no crashes, no NaN, victory reached
933	  {
934	    G.reset(); G.noEvent(() => startGame(false));
935	    let crashed = false;
936	    try {
937	      for (let w = 1; w <= TOTAL_WAVES && mode !== 'win'; w++) {
938	        mode = 'build'; G.noEvent(() => callWave(false));
939	        R(90);              // let the wave spawn and fight for 1.5s
940	        G.wipeEnemies();    // clear the remainder (incl. queue)
941	        R(3);               // endWave fires → build / draft / win
942	        if (mode === 'draft') {
