769	  completeAllTasks: () => { groups.forEach((g, gi) => g.targets.forEach((t, i) => hitTarget(gi, i))); tasksDone = groups.filter(g => g.done).length; checkWin(); },
770	  simulateBumper: (i = 0) => { bumpers[i].cd = 0; onBumper(i); },
771	  simulateRing: (i = 0) => { rings[i].cd = 0; onRing(i); },
