773	  forceFail: () => { ballsLeft = 0; balls = []; loseGame(); },
774	  forceDrain: () => { for (const b of balls) b.y = 910; },
775	  reportProgress: () => { report('progress', { score, progress: progressPct(), tasks: tasksDone }); return progressPct(); },
776	  state: () => ({
777	    mode, paused, score, best, ballsLeft, liveBalls: balls.length,
778	    multiplier, combo, comboT: +comboT.toFixed(3), comboMult: +(1 + Math.min(combo, 10) * 0.2).toFixed(2),
779	    tasksDone, targetScore: TARGET_SCORE, charging, charge: +charge.toFixed(3),
780	    servePending, serveT: +serveT.toFixed(2), playT: +playT.toFixed(2),
781	    nan: nanFlag, muted, newBest,
782	    win: mode === 'complete', over: mode === 'over',
783	    groups: groups.map(g => ({ label: g.label, done: g.done, lit: g.targets.map(t => t.lit) })),
784	    targetsLit: groups.reduce((n, g) => n + g.targets.filter(t => t.lit).length, 0),
785	    flippers: { left: +flippers[0].angle.toFixed(3), right: +flippers[1].angle.toFixed(3), leftPressed: flippers[0].pressed, rightPressed: flippers[1].pressed },
786	    leftRest: FLIP_REST, leftActive: FLIP_ACTIVE,
787	    balls: balls.map(b => ({ x: +b.x.toFixed(2), y: +b.y.toFixed(2), vx: +b.vx.toFixed(1), vy: +b.vy.toFixed(1), inLane: !!inLane(b) })),
788	    progress: progressPct(), reports: reports.length,
789	  }),
790	  reportLog: () => reports.slice(),
791	  view: () => makeView(),
792	  audio, renderer,
793	  defs: { VW, VH, TABLE, TARGET_SCORE, WALLS, BUMPERS, RINGS, TARGET_GROUPS, FLIP_REST, FLIP_ACTIVE, FLIP_LEN },
794	};
