function doRepair() {
  if (mode !== 'forge' || !player) return false;
  if (player.hp >= stats.maxHp) { toast('机体结构完好，无需维修'); return false; }
  if (repairLeft <= 0) { toast('每场整备只能维修一次'); return false; }
