      boss: boss ? {
        x: +boss.x.toFixed(2), y: +boss.y.toFixed(2), hp: +boss.hp.toFixed(2), maxHp: boss.maxHp,
        r: boss.r, enraged: boss.enraged, attack: boss.attack ? boss.attack.kind : '',
