  pressed.clear();
}
addEventListener('keydown', (e) => {
  const c = e.code;
  if (['KeyW', 'KeyA', 'KeyS', 'KeyD', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'Space', 'KeyJ', 'KeyK', 'KeyE', 'KeyP', 'KeyM', 'KeyR', 'ShiftLeft', 'ShiftRight', 'Enter'].includes(c)) {
    e.preventDefault();
  }
  if (['KeyJ', 'KeyK', 'KeyE', 'KeyP', 'KeyM', 'KeyR', 'ShiftLeft', 'ShiftRight', 'Enter', 'Space'].includes(c)) maybeUnlock(e);
  held.add(c);
  if (!e.repeat) pressed.add(c);
});
addEventListener('keyup', (e) => { held.delete(e.code); });
addEventListener('blur', () => { held.clear(); pressed.clear(); });

function updateAimFromClient(clientX, clientY) {
  if (!player || mode !== 'combat') return;
  const w = renderer.screenToWorld(clientX, clientY);
  player.aim = Math.atan2(w.y - player.y, w.x - player.x);
  aimManual = true;
}
cv.addEventListener('pointermove', (e) => {
  updateAimFromClient(e.clientX, e.clientY);
});
cv.addEventListener('pointerdown', (e) => {
  if (e.button !== 0 || mode !== 'combat' || paused) return;
  maybeUnlock(e);
  updateAimFromClient(e.clientX, e.clientY);
  if (e.pointerType === 'mouse' || e.pointerType === 'pen') {
    aimManual = true; mouseDown = true;
