R(85);
ok(12, wasOverheated && shotsAfter === shotsAtOverheat && G.state().player.overheatT <= 0,
  `过热锁定 ${wasOverheated}，锁定期间不再射击（${shotsAtOverheat}→${shotsAfter}），冷却解除`);

