#heatfill{background:linear-gradient(90deg,#d0571e,#ff9d39,#ffe08a)}
#heatfill.hot{background:linear-gradient(90deg,#ff3116,#ff7b32,#ffd06d);animation:heatpulse .4s infinite alternate}
@keyframes heatpulse{to{filter:brightness(1.35)}}
#corefill{background:linear-gradient(90deg,#6c4b17,#e7aa48,#fff0ba)}
.barrow .num{width:62px;text-align:right;color:#e3cda9;font-size:9.5px;font-variant-numeric:tabular-nums;flex:none}
.barrow .num.warn{color:#ff8a55}
.hudbottom{position:absolute;left:16px;bottom:12px;font-size:10px;line-height:1.6;color:rgba(225,205,173,.68);letter-spacing:.5px;max-width:52vw;text-shadow:0 1px 5px #000}
.hudbottom b{color:#ffca7d}
.rightpanel{position:absolute;right:14px;top:62px;text-align:right;font-size:11px;color:#c8b296;line-height:1.75;text-shadow:0 1px 5px #000}
.rightpanel b{color:#ffd382;font-size:14px;font-variant-numeric:tabular-nums}
.rightpanel .clock{font-size:19px;color:#ffe5ad;letter-spacing:1.5px;font-variant-numeric:tabular-nums}
.statusline{position:absolute;top:132px;left:20px;font-size:10px;letter-spacing:2px;color:#9be0d0;text-shadow:0 1px 4px #000}
.statusline.warn{color:#ff955a}
.bossbar{position:absolute;top:13px;left:50%;transform:translateX(-50%);width:min(520px,46vw);pointer-events:none}
#bossname{text-align:center;font-size:11px;letter-spacing:3px;color:#ffd0a0;margin-bottom:4px;text-shadow:0 0 12px rgba(255,90,30,.45),0 1px 4px #000;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#bossname::before,#bossname::after{content:"◆";color:#e68c48;font-size:8px;margin:0 8px;vertical-align:2px;opacity:.6}
.bosstrack{height:13px;background:rgba(8,5,4,.88);border:1px solid rgba(255,128,55,.38);border-radius:7px;overflow:hidden;box-shadow:0 0 16px rgba(255,70,20,.12),inset 0 0 8px rgba(0,0,0,.65)}
#bossfill{height:100%;border-radius:6px;background:linear-gradient(90deg,#bf3c21,#ef7138,#ffc56b);box-shadow:0 0 12px rgba(255,100,40,.35);transition:width .1s linear}
.bossmeta{display:flex;justify-content:space-between;font-size:9px;color:#b88e68;letter-spacing:1.5px;margin-top:3px;padding:0 3px}
.bossmeta b{color:#ffb86b}

